# Variant of 0934a4d8
# Dimension: D1 — 对称类型 (match_cond)
# Change: 双轴对称（LR + UD），反射轴位于 [lo..N-1] 区间的中心... → 仅单轴对称（LR 或 UD）

from __future__ import annotations

import sys
from pathlib import Path

import numpy as np

sys.path.append(str(Path(__file__).resolve().parents[5] / "solvers"))
from arc_utils import bbox

# Design analysis
# a) Concrete behavior and trace:
#    - Original task: every hidden marker cell could be resolved from the 4-cell
#      orbit generated by LR and UD reflections on the [lo..N-1] block; if all
#      reflected copies were also hidden, the solver used a transpose fallback.
#    - Variant: the clean grid keeps only one reflection type, either LR or UD.
#      The solver must first infer which axis is present, then copy each marker
#      cell from its single mirror partner on the other side of that axis.
#    - Example at lo=2, N=30, LR case:
#      cell (7, 5) used to have orbit {(7,5),(7,26),(24,5),(24,26)}. Now only
#      (7,26) is meaningful. If the marker covered both columns 5 and 26, the
#      value would become unrecoverable, so the generator forbids such placement.
# b) Complexity calibration:
#    - Keeping only one axis removes the old redundancy, but the grid is still
#      large, colorful, and globally structured, so the symmetry remains visible.
#    - To avoid trivial/degenerate samples, the generator rejects any input whose
#      visible pixels also satisfy the other reflection axis.
# c) Hidden assumptions from the old main():
#    - `_find_reflected_strip_start` assumed both LR and UD had to hold for the
#      same lo. This is no longer valid; we now search for exactly one (axis, lo).
#    - `_reflection_orbit_values` merged both reflections into one orbit and could
#      tolerate multiple visible copies. In the variant each marker cell must have
#      exactly one visible mirror counterpart, so the solver now reads only that
#      partner and the generator guarantees it is outside the marker.
#    - The transpose fallback relied on doubly-hidden cells near the free border.
#      That mechanism contradicts the single-axis rule, so it is removed entirely.
# d) Placement legality:
#    - LR samples: the marker rectangle must lie fully inside columns [lo..N-1],
#      and its reflected column interval must be disjoint from itself.
#    - UD samples: the symmetric condition is applied to rows instead of columns.
#    - These constraints ensure no marker pixel is out of the mirrored strip and
#      no pixel's only mirror partner is also hidden.
# e) Visual observability:
#    - Across examples, some grids are LR-only and others UD-only.
#    - The non-chosen axis is intentionally not enforced, so humans can see the
#      missing symmetry by comparing opposite rows/columns away from the marker.
# f) Visual cleanliness:
#    - The marker remains a single solid rectangle of one special color, clearly
#      separated from the surrounding mirrored texture.
#    - There are no overlapping objects or secondary fallback cues.
# g) Color inference:
#    - Colors are copied directly from a visible mirror mate; no color remapping,
#      sorting, or invisible ID-based logic is introduced.


def _solid_rectangle_marker(g: np.ndarray) -> tuple[int, tuple[int, int, int, int]]:
    candidates: list[tuple[int, int, tuple[int, int, int, int]]] = []
    for color in np.unique(g):
        mask = g == int(color)
        b = bbox(mask)
        assert b is not None
        r0, c0, r1, c1 = b
        area = int((r1 - r0 + 1) * (c1 - c0 + 1))
        if area > 1 and int(mask.sum()) == area and bool(np.all(mask[r0 : r1 + 1, c0 : c1 + 1])):
            candidates.append((area, int(color), b))

    assert len(candidates) == 1
    _area, color, b = candidates[0]
    return color, b


def _strip_matches_axis(g: np.ndarray, marker: int, lo: int, axis: str) -> bool:
    n, m = map(int, g.shape)
    assert n == m
    hi = n - 1

    if axis == "lr":
        strip = g[:, lo : hi + 1]
        reflected = strip[:, ::-1]
    else:
        strip = g[lo : hi + 1, :]
        reflected = strip[::-1, :]

    known = (strip != marker) & (reflected != marker)
    return not bool(np.any((strip != reflected) & known))


def _all_reflection_candidates(g: np.ndarray, marker: int) -> list[tuple[str, int]]:
    n, m = map(int, g.shape)
    assert n == m

    candidates: list[tuple[str, int]] = []
    for lo in range(n // 2 + 1):
        for axis in ("lr", "ud"):
            if _strip_matches_axis(g, marker, lo, axis):
                candidates.append((axis, lo))
    return candidates


def _find_single_reflection(g: np.ndarray, marker: int) -> tuple[str, int]:
    candidates = _all_reflection_candidates(g, marker)
    assert len(candidates) == 1, f"expected one reflection mode, got {candidates}"
    return candidates[0]


def _mirror_partner(r: int, c: int, lo: int, axis: str, n: int) -> tuple[int, int] | None:
    hi = n - 1
    if axis == "lr":
        if not (lo <= c <= hi):
            return None
        return int(r), int(lo + hi - c)
    if not (lo <= r <= hi):
        return None
    return int(lo + hi - r), int(c)


def _orthogonal_mismatch_count(g: np.ndarray, marker: int, lo: int, axis: str) -> int:
    other = "ud" if axis == "lr" else "lr"
    n = int(g.shape[0])
    hi = n - 1

    if other == "lr":
        strip = g[:, lo : hi + 1]
        reflected = strip[:, ::-1]
    else:
        strip = g[lo : hi + 1, :]
        reflected = strip[::-1, :]

    known = (strip != marker) & (reflected != marker)
    return int(np.count_nonzero((strip != reflected) & known))


def main(grid: np.ndarray) -> np.ndarray:
    """
    Recover the rectangle hidden by the solid marker using whichever single reflection axis the grid still preserves.

    Input structure:
    - A square colored grid contains one solid rectangular marker that occludes the answer patch.
    - Outside the marker, the clean pattern is mirror-symmetric on the centered strip [lo..N-1] in exactly one direction:
      either left-right for all rows or up-down for all columns.
    - The other direction is unconstrained noise, so there is no transpose or second-axis backup.

    Rule:
    - Locate the unique color whose whole extent forms a filled rectangle; that rectangle is the output window.
    - Determine the only reflection mode `(axis, lo)` that is globally consistent when marker cells are ignored.
    - For each hidden cell, copy the color from its unique partner across that detected axis.

    Key insight:
    The marker removes one side of a one-axis mirror pattern, so the missing rectangle is reconstructed by first identifying
    whether the surviving symmetry is horizontal or vertical and then reading the mirrored counterpart of each covered pixel.
    """
    g = np.asarray(grid, dtype=int)
    marker, (r0, c0, r1, c1) = _solid_rectangle_marker(g)
    axis, lo = _find_single_reflection(g, marker)

    h = int(r1 - r0 + 1)
    w = int(c1 - c0 + 1)
    out = np.empty((h, w), dtype=int)

    for rr in range(h):
        for cc in range(w):
            r = int(r0 + rr)
            c = int(c0 + cc)
            partner = _mirror_partner(r, c, lo, axis, int(g.shape[0]))
            assert partner is not None
            pr, pc = partner
            value = int(g[pr, pc])
            assert value != marker
            out[rr, cc] = value

    return out


# --------------- generator (o5x) ---------------

# --- CFG: canvas & structure ---
_N = 30
_LO = 2
_HI = _N - 1
_AXES = ("lr", "ud")

# --- CFG: colors ---
_PALETTE = np.array([1, 2, 3, 4, 5, 6, 7, 9], dtype=int)
_MARKER = 8

# --- CFG: marker rectangle size ---
_MARKER_DIM_LO = 3
_MARKER_DIM_HI = 9
_MARKER_AREA_LO = 16
_MARKER_AREA_HI = 36

# --- CFG: generation retries ---
_MAX_RETRIES = 300

_RNG = np.random.default_rng()
_SIZE_PAIRS = [
    (h, w)
    for h in range(_MARKER_DIM_LO, _MARKER_DIM_HI + 1)
    for w in range(_MARKER_DIM_LO, _MARKER_DIM_HI + 1)
    if _MARKER_AREA_LO <= h * w <= _MARKER_AREA_HI
]
_PLACEMENT_CACHE: dict[tuple[str, int, int], list[tuple[int, int]]] = {}


def _marker_interval_is_valid(start: int, span: int) -> bool:
    end = start + span - 1
    for idx in range(start, end + 1):
        mirror = _LO + _HI - idx
        if start <= mirror <= end:
            return False
    return True


def _valid_placements(axis: str, h: int, w: int) -> list[tuple[int, int]]:
    key = (axis, h, w)
    if key not in _PLACEMENT_CACHE:
        placements: list[tuple[int, int]] = []
        for r0 in range(_N - h + 1):
            for c0 in range(_N - w + 1):
                if axis == "lr":
                    if c0 < _LO or not _marker_interval_is_valid(c0, w):
                        continue
                else:
                    if r0 < _LO or not _marker_interval_is_valid(r0, h):
                        continue
                placements.append((r0, c0))
        _PLACEMENT_CACHE[key] = placements
    return _PLACEMENT_CACHE[key]


def _build_clean(axis: str) -> np.ndarray:
    half = (_N - _LO) // 2
    clean = np.empty((_N, _N), dtype=int)

    if axis == "lr":
        left = _RNG.choice(_PALETTE, size=(_N, half))
        clean[:, _LO : _LO + half] = left
        clean[:, _LO + half : _N] = left[:, ::-1]
        clean[:, :_LO] = _RNG.choice(_PALETTE, size=(_N, _LO))
    else:
        top = _RNG.choice(_PALETTE, size=(half, _N))
        clean[_LO : _LO + half, :] = top
        clean[_LO + half : _N, :] = top[::-1, :]
        clean[:_LO, :] = _RNG.choice(_PALETTE, size=(_LO, _N))

    return clean


def _gen_attempt() -> np.ndarray | None:
    axis = _AXES[int(_RNG.integers(len(_AXES)))]
    clean = _build_clean(axis)
    h, w = _SIZE_PAIRS[int(_RNG.integers(len(_SIZE_PAIRS)))]
    placements = _valid_placements(axis, h, w)
    if not placements:
        return None
    r0, c0 = placements[int(_RNG.integers(len(placements)))]

    expected = clean[r0 : r0 + h, c0 : c0 + w].copy()
    inp = clean.copy()
    inp[r0 : r0 + h, c0 : c0 + w] = _MARKER

    try:
        found_axis, found_lo = _find_single_reflection(inp, _MARKER)
        if (found_axis, found_lo) != (axis, _LO):
            return None
        if _orthogonal_mismatch_count(inp, _MARKER, found_lo, found_axis) == 0:
            return None
        if np.array_equal(main(inp), expected):
            return inp
    except Exception:
        return None
    return None


def generate_input() -> np.ndarray:
    for _ in range(_MAX_RETRIES):
        grid = _gen_attempt()
        if grid is not None:
            return grid
    raise RuntimeError("failed to generate a valid 0934a4d8 D1 input")
